WITH flattened_attrs AS (SELECT id, plan, discounts, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT plan, COUNT(CASE WHEN plan = 'basic' THEN 1 END) AS basic_count, COUNT(*) FILTER (WHERE plan = 'basic') AS basic_rows FROM flattened_attrs GROUP BY plan HAVING COUNT(*) FILTER (WHERE plan = 'basic') >= 1 ORDER BY basic_rows DESC NULLS LAST;
